-- A fence-capable rollback cannot silently downgrade a completed transition.
CREATE TRIGGER sync_cutover_no_delete BEFORE DELETE ON sync_authority_cutovers
BEGIN SELECT RAISE(ABORT, 'b15_dataset_authority_unavailable'); END;

-- Cleanup holds a durable claim while outside D1 in R2. Cutover cannot pass a claim.
-- A crashed claim requires operator recovery; it never expires into an unsafe delete.
CREATE TABLE sync_authority_cleanup_claims (
 account_id TEXT PRIMARY KEY, asset_id TEXT NOT NULL, created_at INTEGER NOT NULL
);

-- Legacy unresolved claims remain reserved; they cannot be cancelled by a timer or old Worker.
CREATE TRIGGER sync_asset_claim_no_update BEFORE UPDATE ON sync_authority_cleanup_claims
BEGIN SELECT RAISE(ABORT,'asset_cleanup_conflict'); END;

-- Additive generation binding. Existing ledgers remain NULL and require review;
-- never infer their original generation from today's Account/membership rows.
ALTER TABLE sync_authority_cutovers ADD COLUMN account_generation INTEGER
 CHECK(account_generation IS NULL OR (typeof(account_generation)='integer' AND account_generation BETWEEN 1 AND 9007199254740991));

CREATE TRIGGER sync_cutover_generation_immutable BEFORE UPDATE ON sync_authority_cutovers
WHEN NEW.account_generation IS NOT OLD.account_generation OR NEW.membership_generation IS NOT OLD.membership_generation
BEGIN SELECT RAISE(ABORT,'b15_migration_generation_stale'); END;
